import numpy as np

def lower_median(values):
    values = np.array(values)
    n = len(values)
    if n == 0:
        raise ValueError("The input array is empty")
    sorted_values = np.sort(values)
    if n % 2 == 1:
        return float(sorted_values[n // 2])
    else:
        return float(sorted_values[n // 2 - 1])
```

